import * as T from './vendor/three.module.js';
export function createMotionState(arms,items,camera){
 const nodes=[],names=[],add=(n,label)=>{if(n&&!nodes.includes(n)){nodes.push(n);names.push(label);}};
 arms.forEach((a,i)=>{add(a.root,`arm${i}/root`);a.joints.forEach((n,j)=>add(n,`arm${i}/joint${j}`));add(a.hand,`arm${i}/hand`);add(a.tcp,`arm${i}/tcp`);add(a.gripper.root,`arm${i}/gripper`);a.gripper.joints?.forEach((j,k)=>add(j.pivot,`arm${i}/finger_joint${k}`));a.gripper.fingers?.forEach((n,k)=>add(n,`arm${i}/finger${k}`));});items.forEach((b,i)=>add(b.mesh,`object${i}`));
 const replayCamera=camera.clone(false),schema={version:1,node_names:names,transform_fields:['px','py','pz','qx','qy','qz','qw','sx','sy','sz'],arm_fields:['j1','j2','j3','j4','j5','j6','tcp_x','tcp_y','tcp_z','closed','held_object_index','opening','tip_z','requested_opening','gripper_angle','tool_offset'],camera_fields:['px','py','pz','qx','qy','qz','qw','aspect','fov','near','far','zoom','projection_matrix_column_major_16'],grippers:arms.map(a=>a.gripper.kind),objects:items.map(b=>({label:b.label,asset:b.assetStyle||'original'})),units:'scene transforms; joint radians; camera matrix projection; 2.8 scene units per meter'};
 function capture(elapsed_s){const transforms=new Float32Array(nodes.length*10),armData=new Float32Array(arms.length*16),c=new Float32Array(28);nodes.forEach((n,i)=>{n.position.toArray(transforms,i*10);n.quaternion.toArray(transforms,i*10+3);n.scale.toArray(transforms,i*10+7);});arms.forEach((a,i)=>armData.set([...a.angles,...a.actual.toArray(),+a.closed,items.indexOf(a.held),a.gripper.opening,a.gripper.tipZ,a.gripper.requested??0,a.gripper.angle??0,a.toolOffset],i*16));camera.getWorldPosition(new T.Vector3()).toArray(c);camera.getWorldQuaternion(new T.Quaternion()).toArray(c,3);c.set([camera.aspect,camera.fov,camera.near,camera.far,camera.zoom],7);c.set(camera.projectionMatrix.elements,12);return {elapsed_s,transforms,arms:armData,camera:c};}
 function apply(s){nodes.forEach((n,i)=>{n.position.fromArray(s.transforms,i*10);n.quaternion.fromArray(s.transforms,i*10+3).normalize();n.scale.fromArray(s.transforms,i*10+7);n.updateMatrix();});arms.forEach((a,i)=>{const o=i*16;a.angles=Array.from(s.arms.subarray(o,o+6));a.actual.fromArray(s.arms,o+6);a.closed=!!s.arms[o+9];a.held=items[s.arms[o+10]]||null;a.gripper.opening=s.arms[o+11];a.gripper.tipZ=s.arms[o+12];a.gripper.requested=s.arms[o+13];a.gripper.angle=s.arms[o+14];a.toolOffset=s.arms[o+15];a.root.updateMatrixWorld(true);});items.forEach(b=>b.mesh.updateMatrixWorld(true));replayCamera.position.fromArray(s.camera);replayCamera.quaternion.fromArray(s.camera,3).normalize();[replayCamera.aspect,replayCamera.fov,replayCamera.near,replayCamera.far,replayCamera.zoom]=s.camera.subarray(7,12);replayCamera.projectionMatrix.fromArray(s.camera,12);replayCamera.projectionMatrixInverse.copy(replayCamera.projectionMatrix).invert();replayCamera.updateMatrixWorld(true);}
 return {schema,capture,apply,replayCamera,nodes};
}
export function motionFramePlan(states,fps,maxFrames=300){const end=states.at(-1)?.elapsed_s||0,count=Math.min(maxFrames,Math.max(1,Math.floor(end*fps)+1)),plan=[];let j=0;for(let i=0;i<count;i++){const t=i/fps;while(j+1<states.length&&states[j+1].elapsed_s<=t)j++;plan.push({time:t,motionIndex:j});}return plan;}
